    {"symbol": "🧱", "tooltip": "Invalidation is only the first course of bricks; an accountability floor must be built where the waiver used to stand."}
  ],
  "claim_sketches": [
    {"claim": "A waiver a user never reads cannot lower the duty the deploying firm owes them, because negligence law attaches the standard of care to the actor, not the tool.", "targets": [], "relationship": "extends"},
    {"claim": "A contractual disclaimer between a firm and its users cannot bind third parties who never agreed to it, so waiver-by-boilerplate fails exactly where accountability matters most.", "targets": ["AN-3"], "relationship": "extends"},
    {"claim": "Nasr et al. (2023) demonstrated that targeted finetuning can extract long verbatim passages from a model's training set, so a waiver written as if AI interactions were transient communications cannot supply informed consent to retention and extraction risk.", "targets": [], "relationship": "extends"},
