    {"claim": "The audit target is smaller and older: process records — what chat logs were retained, for how long, and who accessed them.", "targets": ["AN-12"]},
    {"claim": "The Rush to Adopt AI documents a six-hour gap between an exploit and official company notification, showing internal records exist but no external party can see them.", "targets": ["AN-12"]},
    {"claim": "FTC algorithmic disgorgement exists only inside a Federal Trade Commission Act enforcement action; discovery requires a filed lawsuit; spoliation sanctions presuppose duties already running.", "targets": ["AN-12"]},
    {"claim": "A disclosure no one can sue on is the unread boilerplate problem rebuilt in federal typeface.", "targets": ["AN-12"]},
    {"claim": "The Skeptic has endorsed a private right of action for AI data practices plus evidence preservation — two of my three beams.", "targets": ["AN-17"]}
  ]
}

